async function openDirect(peerId){if(!self||!online||opening){setStatus('يلزم الاتصال بالإنترنت لبدء المحادثة.',true);return;}const peer=(Array.isArray(users)?users:[]).find(u=>String(u.id)===String(peerId));if(!peer||String(peer.id)===self.id){setStatus('اختر مستخدماً آخر.',true);return;}const pair=[pathKey(self.id),pathKey(peer.id)].sort(),id='dm_'+pair.join('_'),me={...self};opening=true;const token=epoch;
 try{const ref=fbDB.ref(ROOM_ROOT+'/rooms/'+id);const result=await ref.transaction(current=>current||{type:'direct',members:{[pair[0]]:true,[pair[1]]:true},memberNames:{[pathKey(me.id)]:me.name,[pathKey(peer.id)]:String(peer.name||peer.username||'مستخدم')},createdBy:me.id,createdAt:now()});if(token!==epoch)return;const meta=checkRoom(result.snapshot.val(),id);if(Object.keys(meta.members).sort().join('_')!==pair.join('_')||meta.type!=='direct')throw Error('تعارض في بيانات المحادثة');const updates={};for(const key of pair)updates['inboxes/'+key+'/'+id]=meta;await fbDB.ref(ROOM_ROOT).update(updates);if(token!==epoch)return;rooms.set(id,meta);syncPreviews();attachRoom(id,meta);
 }catch(e){if(token===epoch)setStatus('تعذر فتح المحادثة: '+e.message,true);}finally{opening=false;}}
