 services:{label:'الخدمات والعدادات',actions:['view','add','edit','delete','print','prices']},
 kambiyala:{label:'الكمبيالات',actions:['view','add','edit','delete','print']},
 cheques:{label:'الشيكات الواردة',actions:['view','add','edit','deleteAll','export','import','settle']},
 maintenance:{label:'الصيانة',actions:['view','add','print']},
 purchases:{label:'المشتريات',actions:['view','add','edit','status','print']},
